#if PATHY_PUBLIC
    public static class ChainablePathGlobbingExtensions
#else
    [global::Microsoft.CodeAnalysis.Embedded]
    [global::System.Diagnostics.DebuggerNonUserCode]
    internal static class ChainablePathGlobbingExtensions
